from collections import Counter
import math
import re


def _clean_text(text: str) -> str:
    return re.sub(r"[\W_]+", " ", text.lower())


def _lcs_length(s1: str, s2: str) -> int:
    if len(s1) < len(s2):
        s1, s2 = s2, s1
    if not s2:
        return 0

    masks: dict[str, int] = {}
    for i, ch in enumerate(s2):
        masks[ch] = masks.get(ch, 0) | (1 << i)

    v = 0
    for ch in s1:
        x = v | masks.get(ch, 0)
        v = x & ((x - ((v << 1) | 1)) ^ x)

    return bin(v).count("1")


def text_similarity_scores(text1: str, text2: str) -> tuple[float, float]:
    clean1 = _clean_text(text1)
    clean2 = _clean_text(text2)

    words1 = clean1.split()
    words2 = clean2.split()
    if not words1 or not words2:
        cosine = 0.0
    else:
        counts1 = Counter(words1)
        counts2 = Counter(words2)
        dot = sum(counts1[w] * counts2[w] for w in counts1.keys() & counts2.keys())
        norm1 = math.sqrt(sum(v * v for v in counts1.values()))
        norm2 = math.sqrt(sum(v * v for v in counts2.values()))
        cosine = min(1.0, dot / (norm1 * norm2))

    total_len = len(clean1) + len(clean2)
    if total_len == 0:
        ratio = 1.0
    else:
        lcs = _lcs_length(clean1, clean2)
        ratio = (2.0 * lcs) / total_len

    return (cosine, ratio)
```

