To compute the pairwise Pearson correlation of letter counts across a list of strings, you can count the occurrences of each letter per string and apply the Pearson correlation formula:

$$r_{xy} = \frac{n\sum x_i y_i - \sum x_i \sum y_i}{\sqrt{(n\sum x_i^2 - (\sum x_i)^2)(n\sum y_i^2 - (\sum y_i)^2)}}$$

Using integer arithmetic for the sums avoids intermediate floating-point rounding errors from fractional means.

```python
from collections import Counter
import math


def letter_count_correlations(strings):
    if not strings:
        return None

    n = len(strings)
    per_string_counts = [Counter(ch for ch in s if ch.isalpha()) for s in strings]
    letters = sorted({ch for counts in per_string_counts for ch in counts})

    counts_by_letter = {
        ch: [counts[ch] for counts in per_string_counts]
        for ch in letters
    }

    # Precompute n * sum(x^2) - (sum x)^2 and sum(x) for each letter
    sums = {ch: sum(vals) for ch, vals in counts_by_letter.items()}
    var_terms = {
        ch: n * sum(v * v for v in vals) - sums[ch] ** 2
        for ch, vals in counts_by_letter.items()
    }

    result = {ch: {} for ch in letters}
    for i, x in enumerate(letters):
        result[x][x] = 1.0
        xs = counts_by_letter[x]
        for y in letters[i + 1 :]:
            ys = counts_by_letter[y]
            num = n * sum(a * b for a, b in zip(xs, ys)) - sums[x] * sums[y]
            den = math.sqrt(var_terms[x] * var_terms[y])
            corr = max(-1.0, min(1.0, num / den))
            result[x][y] = corr
            result[y][x] = corr

    return result
```

