```python
from html.parser import HTMLParser

_VOID_ELEMENTS = frozenset({
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr',
})


class _FirstTagTextParser(HTMLParser):
    def __init__(self, target_tag: str):
        super().__init__(convert_charrefs=True)
        self.target_tag = target_tag.lower()
        self.depth = 0
        self.done = False
        self.chunks = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        if tag == self.target_tag:
            if tag in _VOID_ELEMENTS:
                self.done = True
            else:
                self.depth += 1

    def handle_endtag(self, tag):
        if self.done:
            return
        if self.depth > 0 and tag == self.target_tag:
            self.depth -= 1
            if self.depth == 0:
                self.done = True

    def handle_data(self, data):
        if self.depth > 0 and not self.done:
            self.chunks.append(data)


def first_tag_text(html: str, tag: str) -> str | None:
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()
    text = ''.join(parser.chunks)
    return text if text else None
```

### How it works
- **Nested elements & same-tag nesting:** It tracks `depth` for the target tag so nested elements (including another element with the same tag name) are included until the first matching element closes.
- **Entity decoding:** `HTMLParser(..., convert_charrefs=True)` automatically decodes named and numeric HTML entities (e.g., `&amp;`, `&lt;`, `&#39;`).
- **Void / self-closing tags:** Void elements (like `<br>` or `<img>`) and self-closing tags (like `<p/>`) terminate immediately so they don't capture subsequent document text.
- **Empty or missing elements:** Returns `None` if the element is not found or if the extracted text is `""`.

