import csv
import io
import re
from datetime import date

_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _parse_date(value: str) -> date:
    if not isinstance(value, str) or not _DATE_RE.match(value):
        raise ValueError(f"Invalid date format (expected 'YYYY-MM-DD'): {value!r}")
    return date.fromisoformat(value)


def filter_rows_by_date_range(
    csv_text: str, column_name: str, start_date: str, end_date: str
) -> list[list[str]]:
    start = _parse_date(start_date)
    end = _parse_date(end_date)

    reader = csv.reader(io.StringIO(csv_text))
    header = next(reader, None)
    if header is None or column_name not in header:
        raise ValueError(f"Column {column_name!r} not found in CSV header.")

    col_idx = header.index(column_name)
    matching_rows = []

    for row in reader:
        if col_idx >= len(row):
            continue
        try:
            row_date = _parse_date(row[col_idx])
        except ValueError:
            continue
        if start <= row_date <= end:
            matching_rows.append(row)

    return matching_rows
```

