```python
import csv
import io
import math


def _parse_float(value_str):
    try:
        val = float(value_str)
    except ValueError as exc:
        raise ValueError(f"Non-numeric or missing value: {value_str!r}") from exc
    if not math.isfinite(val):
        raise ValueError(f"Non-finite value: {value_str!r}")
    return val


def _read_csv_rows(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("CSV input must be a string")
    reader = csv.reader(io.StringIO(csv_text, newline=""))
    rows = list(reader)
    if not rows:
        raise ValueError("CSV input is empty")
    return rows


def _col_norm(mat, col, start_row=0):
    rows = len(mat)
    max_val = 0.0
    for i in range(start_row, rows):
        v = abs(mat[i][col])
        if v > max_val:
            max_val = v
    if max_val == 0.0:
        return 0.0
    return max_val * math.sqrt(
        sum((mat[i][col] / max_val) ** 2 for i in range(start_row, rows))
    )


def _jacobi_svd(W, max_sweeps=60):
    """One-sided Jacobi SVD on an r x c matrix W (r >= c), modified in place."""
    r = len(W)
    c = len(W[0])
    V = [[1.0 if i == j else 0.0 for j in range(c)] for i in range(c)]

    if c > 1:
        eps = 1e-15
        for _ in range(max_sweeps):
            converged = True
            for i in range(c - 1):
                for j in range(i + 1, c):
                    a = 0.0
                    b = 0.0
                    d = 0.0
                    for k in range(r):
                        wi = W[k][i]
                        wj = W[k][j]
                        a += wi * wi
                        b += wj * wj
                        d += wi * wj
                    if d == 0.0 or abs(d) <= eps * math.sqrt(a) * math.sqrt(b):
                        continue
                    converged = False
                    zeta = (b - a) / (2.0 * d)
                    t = 1.0 / (abs(zeta) + math.hypot(1.0, zeta))
                    if zeta < 0.0:
                        t = -t
                    cs = 1.0 / math.hypot(1.0, t)
                    sn = cs * t
                    for k in range(r):
                        wi = W[k][i]
                        wj = W[k][j]
                        W[k][i] = cs * wi - sn * wj
                        W[k][j] = sn * wi + cs * wj
                    for k in range(c):
                        vi = V[k][i]
                        vj = V[k][j]
                        V[k][i] = cs * vi - sn * vj
                        V[k][j] = sn * vi + cs * vj
            if converged:
                break

    sigmas = [_col_norm(W, j) for j in range(c)]
    return W, V, sigmas


def _solve_ols(X, y):
    n = len(X)
    p = len(X[0])
    eps = 2.220446049250313e-16

    if n >= p:
        A = [row[:] for row in X]
        qy = y[:]
        for k in range(p):
            norm_x = _col_norm(A, k, start_row=k)
            if norm_x == 0.0:
                continue
            x0 = A[k][k]
            alpha = -norm_x if x0 >= 0.0 else norm_x
            v = [x0 - alpha] + [A[i][k] for i in range(k + 1, n)]
            v_norm_sq = sum(vi * vi for vi in v)
            if v_norm_sq == 0.0:
                continue
            beta_h = 2.0 / v_norm_sq
            A[k][k] = alpha
            for i in range(k + 1, n):
                A[i][k] = 0.0
            for j in range(k + 1, p):
                dot = sum(v[i - k] * A[i][j] for i in range(k, n))
                scale = beta_h * dot
                for i in range(k, n):
                    A[i][j] -= scale * v[i - k]
            dot_y = sum(v[i - k] * qy[i] for i in range(k, n))
            scale_y = beta_h * dot_y
            for i in range(k, n):
                qy[i] -= scale_y * v[i - k]

        R = [A[i][:] for i in range(p)]
        z = qy[:p]
        W, V, sigmas = _jacobi_svd(R)
        max_sigma = max(sigmas) if sigmas else 0.0
        tol = max(n, p) * eps * max_sigma
        beta = [0.0] * p
        for j in range(p):
            s = sigmas[j]
            if s > tol:
                coef = sum(W[k][j] * z[k] for k in range(p)) / (s * s)
                for i in range(p):
                    beta[i] += coef * V[i][j]
        return beta
    else:
        XT = [[X[j][i] for j in range(n)] for i in range(p)]
        W, V, sigmas = _jacobi_svd(XT)
        max_sigma = max(sigmas) if sigmas else 0.0
        tol = max(n, p) * eps * max_sigma
        beta = [0.0] * p
        for j in range(n):
            s = sigmas[j]
            if s > tol:
                coef = sum(V[k][j] * y[k] for k in range(n)) / (s * s)
                for i in range(p):
                    beta[i] += coef * W[i][j]
        return beta


def predict_linear_regression(train_csv, test_csv, target):
    train_rows = _read_csv_rows(train_csv)
    test_rows = _read_csv_rows(test_csv)

    train_header = train_rows[0]
    test_header = test_rows[0]

    if not train_header or target not in train_header:
        raise ValueError(f"Target column {target!r} not found in CSV header")
    if train_header.count(target) != 1:
        raise ValueError(f"Target column {target!r} appears multiple times")
    if len(train_header) != len(test_header) or sorted(train_header) != sorted(test_header):
        raise ValueError("Train and test CSV headers must have the same columns")
    if len(train_rows) < 2:
        raise ValueError("Training CSV has no data rows")

    train_target_idx = train_header.index(target)
    train_feature_indices = [i for i in range(len(train_header)) if i != train_target_idx]
    if train_header == test_header:
        test_feature_indices = train_feature_indices
    else:
        if len(set(train_header)) != len(train_header):
            raise ValueError("Duplicate column names in reordered headers")
        test_col_map = {name: i for i, name in enumerate(test_header)}
        test_feature_indices = [test_col_map[train_header[i]] for i in train_feature_indices]

    num_train_cols = len(train_header)
    X_train = []
    y_train = []
    for row in train_rows[1:]:
        if len(row) != num_train_cols:
            raise ValueError("Row in training CSV has wrong number of columns")
        features = [1.0]
        for idx in train_feature_indices:
            features.append(_parse_float(row[idx]))
        X_train.append(features)
        y_train.append(_parse_float(row[train_target_idx]))

    num_test_cols = len(test_header)
    X_test = []
    for row in test_rows[1:]:
        if len(row) != num_test_cols:
            raise ValueError("Row in test CSV has wrong number of columns")
        features = [1.0]
        for idx in test_feature_indices:
            features.append(_parse_float(row[idx]))
        X_test.append(features)

    if not X_test:
        return []

    beta = _solve_ols(X_train, y_train)
    p = len(beta)
    return [float(sum(beta[j] * row[j] for j in range(p))) for row in X_test]
```

