def normalize_csv_columns(csv_text: str) -> dict[str, list[float]]:
    reader = csv.reader(io.StringIO(csv_text))
    try:
        headers = next(reader)
    except StopIteration:
        return {}

    columns: dict[str, list[float]] = {header: [] for header in headers}
    for row in reader:
        if not row:
            continue
        for header, value in zip(headers, row):
            columns[header].append(float(value))

    normalized: dict[str, list[float]] = {}
    for header in headers:
        values = columns[header]
        if not values:
            normalized[header] = []
            continue

        min_val = min(values)
        max_val = max(values)
        span = max_val - min_val

        if span == 0:
            normalized[header] = [0.0] * len(values)
        else:
            normalized[header] = [(v - min_val) / span for v in values]

    return normalized
