import json


def key_mean_median(json_text):
    records = json.loads(json_text)
    if not records:
        return {}

    values_by_key = {}
    for record in records:
        for key, value in record.items():
            if key not in values_by_key:
                values_by_key[key] = []
            # In Python, bool is a subclass of int, so exclude booleans explicitly
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                values_by_key[key].append(float(value))

    result = {}
    for key, nums in values_by_key.items():
        if not nums:
            result[key] = {"mean": None, "median": None}
        else:
            nums.sort()
            n = len(nums)
            mean_val = sum(nums) / n
            mid = n // 2
            if n % 2 == 1:
                median_val = nums[mid]
            else:
                median_val = (nums[mid - 1] + nums[mid]) / 2.0
            result[key] = {"mean": mean_val, "median": median_val}

    return result
```

