    cols1 = list(dict.fromkeys(k for r in rows1 for k in r if k != 'id'))
    cols2 = list(dict.fromkeys(k for r in rows2 for k in r if k != 'id'))

    map1 = {r['id']: r for r in rows1}
    map2 = {r['id']: r for r in rows2}

    # Compute mean and population std for each feature column in rows1
    stats = {}
    for col in cols1:
