    all_ids = sorted(map1.keys() | map2.keys())
    result = []
    for row_id in all_ids:
        merged = {'id': row_id}
        r1 = map1.get(row_id, {})
        r2 = map2.get(row_id, {})

        for col in cols1:
            val = r1.get(col)
            if val is None:
                merged[col] = None
            else:
                mean, std = stats[col]
                merged[col] = 0.0 if std == 0 else (val - mean) / std

