```python
def seasonal_decomposition(values, period, model):
    if period < 1:
        raise ValueError("period must be at least 1")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series must have at least two complete periods")

    # 1. Centered moving average for the trend
    trend = [None] * n
    half = period // 2
    if period % 2 == 1:
        for i in range(half, n - half):
            trend[i] = sum(values[i - half : i + half + 1]) / period
    else:
        for i in range(half, n - half):
            ma1 = sum(values[i - half : i + half]) / period
            ma2 = sum(values[i - half + 1 : i + half + 1]) / period
            trend[i] = (ma1 + ma2) / 2

    # 2. Detrend and average by seasonal position
    seasonal_buckets = [[] for _ in range(period)]
    for i in range(n):
        if trend[i] is not None:
            if model == "additive":
                detrended = values[i] - trend[i]
            else:
                detrended = values[i] / trend[i]
            seasonal_buckets[i % period].append(detrended)

    raw_seasonal = [sum(bucket) / len(bucket) for bucket in seasonal_buckets]

    # 3. Normalise seasonal indices
    avg_seasonal = sum(raw_seasonal) / period
    if model == "additive":
        norm_seasonal = [s - avg_seasonal for s in raw_seasonal]
    else:
        norm_seasonal = [s / avg_seasonal for s in raw_seasonal]

    seasonal = [norm_seasonal[i % period] for i in range(n)]

    # 4. Residual component
    residual = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == "additive":
                residual[i] = values[i] - trend[i] - seasonal[i]
            else:
                residual[i] = values[i] / (trend[i] * seasonal[i])

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
```

