```python
def seasonal_decomposition(values, period, model):
    if period < 1:
        raise ValueError("Period must be at least 1.")
    n = len(values)
    if n < 2 * period:
        raise ValueError("Series must have at least two complete periods.")
    if model not in ("additive", "multiplicative"):
        raise ValueError("Model must be 'additive' or 'multiplicative'.")

    # 1. Centered moving average for trend
    trend = [None] * n
    if period % 2 == 1:
        half = (period - 1) // 2
        for i in range(half, n - half):
            trend[i] = sum(values[i - half : i + half + 1]) / period
    else:
        half = period // 2
        for i in range(half, n - half):
            window_sum = (
                0.5 * values[i - half]
                + sum(values[i - half + 1 : i + half])
                + 0.5 * values[i + half]
            )
            trend[i] = window_sum / period

    # 2. Detrended series
    detrended = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == "additive":
                detrended[i] = values[i] - trend[i]
            else:
                if trend[i] == 0:
                    raise ValueError("Trend cannot be zero for multiplicative model.")
                detrended[i] = values[i] / trend[i]

    # 3. Raw seasonal averages per phase, then normalize
    phase_sums = [0.0] * period
    phase_counts = [0] * period
    for i, val in enumerate(detrended):
        if val is not None:
            p = i % period
            phase_sums[p] += val
            phase_counts[p] += 1

    phase_avgs = [phase_sums[p] / phase_counts[p] for p in range(period)]
    overall_mean = sum(phase_avgs) / period

    if model == "additive":
        norm_indices = [avg - overall_mean for avg in phase_avgs]
    else:
        if overall_mean == 0:
            raise ValueError("Mean seasonal index cannot be zero for multiplicative model.")
        norm_indices = [avg / overall_mean for avg in phase_avgs]

    seasonal = [norm_indices[i % period] for i in range(n)]

    # 4. Residual component
    residual = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == "additive":
                residual[i] = values[i] - trend[i] - seasonal[i]
            else:
                residual[i] = values[i] / (trend[i] * seasonal[i])

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
```

