    else:
        for i in range(half, n - half):
            interior = sum(values[i - half + 1 : i + half])
            endpoints = 0.5 * (values[i - half] + values[i + half])
            trend[i] = (interior + endpoints) / period

    # 2. Detrended series and raw seasonal averages
    buckets = [[] for _ in range(period)]
    for i in range(n):
        if trend[i] is not None:
