def scale_table_columns(data):
    if not data:
        return {}

    cols = list(data.keys())
    num_rows = len(data[cols[0]])

    # Keep only row indices where no column has a None value
    valid_rows = [
        i for i in range(num_rows)
        if all(data[col][i] is not None for col in cols)
    ]

    if not valid_rows:
        return {col: [] for col in cols}

    result = {}
    for col in cols:
        values = [data[col][i] for i in valid_rows]
        min_val = min(values)
        max_val = max(values)
        span = max_val - min_val

        if span == 0:
            result[col] = [0.0] * len(values)
        else:
            result[col] = [(v - min_val) / span for v in values]

    return result
```

