Here is an implementation using only the Python standard library (with k-means++ initialization and Lloyd's algorithm):

```python
from collections import Counter
import random


def cluster_unique_points(points, n_clusters):
    pts = [tuple(p) for p in points]
    counts = Counter(pts)
    duplicates = {pt: count for pt, count in counts.items() if count > 1}

    unique_points = sorted(counts.keys())
    if not unique_points or n_clusters <= 0:
        return duplicates, []

    k = min(n_clusters, len(unique_points))
    if k == 1:
        return duplicates, [unique_points]
    if k == len(unique_points):
        return duplicates, [[pt] for pt in unique_points]

    def dist_sq(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    rng = random.Random(42)
    best_clusters = None
    best_inertia = float("inf")

    # Run k-means multiple times with k-means++ initialization and keep the best result
    for _ in range(10):
        centroids = [rng.choice(unique_points)]
        for _ in range(1, k):
            weights = [min(dist_sq(p, c) for c in centroids) for p in unique_points]
            total = sum(weights)
            if total == 0:
                centroids.append(rng.choice(unique_points))
            else:
                centroids.append(rng.choices(unique_points, weights=weights, k=1)[0])

        assignments = [-1] * len(unique_points)
        for _ in range(300):
            new_assignments = [
                min(range(k), key=lambda i: dist_sq(p, centroids[i]))
                for p in unique_points
            ]

            # Build clusters and handle any empty cluster by moving the farthest point into it
            groups = [[] for _ in range(k)]
            for idx, cluster_id in enumerate(new_assignments):
                groups[cluster_id].append(idx)

            for empty_id in range(k):
                if not groups[empty_id]:
                    farthest_idx = max(
                        (idx for idx in range(len(unique_points)) if len(groups[new_assignments[idx]]) > 1),
                        key=lambda idx: dist_sq(unique_points[idx], centroids[new_assignments[idx]]),
                    )
                    old_id = new_assignments[farthest_idx]
                    groups[old_id].remove(farthest_idx)
                    groups[empty_id].append(farthest_idx)
                    new_assignments[farthest_idx] = empty_id

            if new_assignments == assignments:
                break
            assignments = new_assignments

            centroids = [
                (
                    sum(unique_points[idx][0] for idx in group) / len(group),
                    sum(unique_points[idx][1] for idx in group) / len(group),
                )
                for group in groups
            ]

        inertia = sum(
            dist_sq(unique_points[idx], centroids[assignments[idx]])
            for idx in range(len(unique_points))
        )
        if inertia < best_inertia:
            best_inertia = inertia
            best_clusters = [
                sorted(unique_points[idx] for idx in group)
                for group in groups
            ]

    return duplicates, sorted(best_clusters)
```

