import math


def column_correlations(data):
    cols = list(data.keys())
    if not cols:
        return {}

    n = len(data[cols[0]])
    centered = {}
    norms = {}

    for col in cols:
        values = data[col]
        if n == 0:
            centered[col] = []
            norms[col] = 0.0
            continue
        mean = sum(values) / n
        diffs = [v - mean for v in values]
        centered[col] = diffs
        norms[col] = math.sqrt(sum(d * d for d in diffs))

    result = {col: {} for col in cols}

    for i, x in enumerate(cols):
        for j in range(i, len(cols)):
            y = cols[j]
            norm_x = norms[x]
            norm_y = norms[y]

            if norm_x == 0.0 or norm_y == 0.0:
                corr = float("nan")
            elif i == j:
                corr = 1.0
            else:
                dot = sum(a * b for a, b in zip(centered[x], centered[y]))
                corr = dot / (norm_x * norm_y)
                # Clamp to [-1.0, 1.0] to avoid minor floating-point overshoot
                corr = max(-1.0, min(1.0, corr))

            result[x][y] = corr
            result[y][x] = corr

    return result
