import math
import numbers


def normalized_cumulative_sums(data):
    if not data:
        raise ValueError("Input data cannot be empty.")

    result = {}
    expected_len = None

    for col, values in data.items():
        if not values:
            raise ValueError(f"Column '{col}' cannot be empty.")
        if expected_len is None:
            expected_len = len(values)
        elif len(values) != expected_len:
            raise ValueError("All columns must have equal length.")

        cumsum = []
        running = 0
        for val in values:
            if isinstance(val, bool) or not isinstance(val, numbers.Real):
                raise TypeError(f"Non-numeric value found in column '{col}': {val!r}")
            if math.isnan(val):
                raise ValueError(f"NaN value found in column '{col}'.")
            running += val
            cumsum.append(running)

        min_val = min(cumsum)
        max_val = max(cumsum)
        span = max_val - min_val

        if span == 0:
            result[col] = [0.0] * len(cumsum)
        else:
            result[col] = [float((x - min_val) / span) for x in cumsum]

    return result
```

### Key details:
- **Type validation**: Checks `isinstance(val, numbers.Real)` while excluding `bool` (since `bool` is a subclass of `int` in Python), raising `TypeError` for non-numeric entries.
- **Empty & NaN validation**: Raises `ValueError` if `data` is empty, if any column list is empty, if column lengths differ, or if any value is `NaN`.
- **Constant cumulative sums**: When `max_val - min_val == 0` (e.g., single-element lists or trailing zeros after an initial value), the column is mapped to `[0.0] * len(cumsum)`.

