Here is the implementation of `standardize_by_group`:

```python
from collections import defaultdict
import math


def standardize_by_group(records):
    required_keys = ("id", "age", "income")
    groups = defaultdict(list)

    for record in records:
        if any(key not in record for key in required_keys):
            raise ValueError("Each record must contain 'id', 'age', and 'income' keys.")
        groups[record["id"]].append(record)

    group_stats = {}
    for group_id, group_records in groups.items():
        n = len(group_records)
        group_stats[group_id] = {}

        for field in ("age", "income"):
            values = [float(r[field]) for r in group_records]
            if all(v == values[0] for v in values):
                group_stats[group_id][field] = (values[0], 0.0)
            else:
                mean = sum(values) / n
                variance = sum((v - mean) ** 2 for v in values) / n
                std = math.sqrt(variance)
                group_stats[group_id][field] = (mean, std)

    result = []
    for record in records:
        group_id = record["id"]
        age_mean, age_std = group_stats[group_id]["age"]
        income_mean, income_std = group_stats[group_id]["income"]

        std_age = 0.0 if age_std == 0.0 else (float(record["age"]) - age_mean) / age_std
        std_income = (
            0.0 if income_std == 0.0 else (float(record["income"]) - income_mean) / income_std
        )

        result.append(
            {
                "id": group_id,
                "age": std_age,
                "income": std_income,
            }
        )

    return result
```

### How it works:
1. **Validation & Grouping**: Iterates through `records`, raising a `ValueError` if any dict lacks `'id'`, `'age'`, or `'income'`, while grouping records by `'id'`.
2. **Group Statistics**: For each group, computes the mean and population standard deviation ($\sqrt{\frac{1}{N}\sum(x_i - \mu)^2}$) for `'age'` and `'income'`. Checking `all(v == values[0] for v in values)` avoids floating-point precision artifacts when all values in a group are identical.
3. **Standardization**: Iterates through `records` in the original input order, outputting new dicts with `'id'` preserved and `'age'`/`'income'` standardized as floats (defaulting to `0.0` when the group standard deviation is `0.0`).

Here is the implementation of `standardize_by_group`:

```python
import math
from collections import defaultdict


def standardize_by_group(records):
    required_keys = ('id', 'age', 'income')
    for record in records:
        if not all(key in record for key in required_keys):
            raise ValueError("Each record must contain 'id', 'age', and 'income' keys.")

    groups = defaultdict(list)
    for record in records:
        groups[record['id']].append(record)

    def calc_stats(values):
        if all(v == values[0] for v in values):
            return 0.0, 0.0
        n = len(values)
        mean = sum(values) / n
        variance = sum((v - mean) ** 2 for v in values) / n
        return mean, math.sqrt(variance)

    group_stats = {}
    for group_id, group_records in groups.items():
        ages = [r['age'] for r in group_records]
        incomes = [r['income'] for r in group_records]
        group_stats[group_id] = (calc_stats(ages), calc_stats(incomes))

    result = []
    for record in records:
