import math


def standardize_columns(rows, columns, features):
    if not rows:
        return []

    n = len(rows)
    feature_set = set(features)
    feature_indices = {i for i, col in enumerate(columns) if col in feature_set}

    means = {}
    stds = {}
    for idx in feature_indices:
        vals = [float(row[idx]) for row in rows]
        if all(v == vals[0] for v in vals):
            means[idx] = 0.0
            stds[idx] = 0.0
        else:
            mean = sum(vals) / n
            variance = sum((v - mean) ** 2 for v in vals) / n
            means[idx] = mean
            stds[idx] = math.sqrt(variance)

    result = []
    for row in rows:
        new_row = []
        for idx, val in enumerate(row):
            fval = float(val)
            if idx in feature_indices:
                std = stds[idx]
                if std == 0.0:
                    new_row.append(0.0)
                else:
                    new_row.append((fval - means[idx]) / std)
            else:
                new_row.append(fval)
        result.append(new_row)

    return result
```

### How it works:
- Identifies the column indices corresponding to `features` using a set lookup.
- For each feature column, checks if all values are identical (handling constant columns directly, including floating-point values like `[0.1, 0.1, 0.1]` where rounding error in the mean might otherwise yield a tiny non-zero standard deviation).
- Otherwise, computes the mean and population standard deviation ($\sqrt{\frac{1}{N}\sum (x_i - \mu)^2}$).
- Builds and returns a new table of `float` values without mutating the input `rows`, rescaling only the specified feature columns.

