            raise ValueError("T must have consistent second dimension.")
        for slice_n in slice_k:
            if len(slice_n) != p:
                raise ValueError("T must have consistent third dimension.")

    # Build the n x (m * p) table
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            p_row = P[i]
            for c in range(p):
                val = sum(p_row[r] * T[r][j][c] for r in range(k))
                row.append(float(val))
        table.append(row)

    # Standardize each column
    num_cols = m * p
    for col_idx in range(num_cols):
        col = [table[j][col_idx] for j in range(n)]
        if all(x == col[0] for x in col):
            for j in range(n):
                table[j][col_idx] = 0.0
            continue

        mean = sum(col) / n
        var = sum((x - mean) ** 2 for x in col) / n
        if var == 0.0:
            for j in range(n):
                table[j][col_idx] = 0.0
        else:
            std = math.sqrt(var)
            for j in range(n):
                table[j][col_idx] = (table[j][col_idx] - mean) / std

