def standardized_tensor_product(P, T):
    if not P or any(not row for row in P):
        raise ValueError("P must be a non-empty 2D matrix.")
    if not T or any(not mat for mat in T) or any(not vec for mat in T for vec in mat):
        raise ValueError("T must be a non-empty 3D tensor.")

    m = len(P)
    k = len(P[0])
    if any(len(row) != k for row in P):
        raise ValueError("P must have uniform row lengths.")

    if len(T) != k:
        raise ValueError("P's number of columns must match T's first dimension.")

    n = len(T[0])
    p = len(T[0][0])
    if any(len(mat) != n or any(len(vec) != p for vec in mat) for mat in T):
        raise ValueError("T must have uniform dimensions.")

    # Build the n x (m * p) table
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            p_row = P[i]
            for l in range(p):
                val = sum(p_row[r] * T[r][j][l] for r in range(k))
                row.append(float(val))
        table.append(row)

    # Standardise each column using population standard deviation
    num_cols = m * p
    for col_idx in range(num_cols):
        first_val = table[0][col_idx]
        if all(table[j][col_idx] == first_val for j in range(1, n)):
            for j in range(n):
                table[j][col_idx] = 0.0
            continue

        mean = sum(table[j][col_idx] for j in range(n)) / n
        var = sum((table[j][col_idx] - mean) ** 2 for j in range(n)) / n
        if var == 0.0:
            for j in range(n):
                table[j][col_idx] = 0.0
        else:
            std = math.sqrt(var)
            for j in range(n):
                table[j][col_idx] = (table[j][col_idx] - mean) / std

    return table
