                if not math.isfinite(num):
                    is_numeric = False
                    break
                numeric_vals.append(num)
            except ValueError:
                is_numeric = False
                break

        if is_numeric:
            mean = sum(numeric_vals) / len(numeric_vals)
            result[col_name] = [
                mean if v.strip() == "" else float(v)
                for v in raw_values
            ]
        else:
            result[col_name] = [
                None if v.strip() == "" else v
                for v in raw_values
            ]

    return result
