def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    result = {}
    for col_name, values in data.items():
        # 1. Replace values present in replacements
        replaced = [replacements[v] if v in replacements else v for v in values]

        # 2. Integer-encode columns containing strings in sorted distinct order
        if any(isinstance(v, str) for v in replaced):
            unique_sorted = sorted(set(replaced))
            code_map = {val: idx for idx, val in enumerate(unique_sorted)}
            encoded = [code_map[v] for v in replaced]
        else:
            encoded = replaced

        # 3. Standardize using mean and sample standard deviation (n - 1)
        n = len(encoded)
        if n == 0:
            result[col_name] = []
        elif n == 1:
            result[col_name] = [0.0]
        else:
            mean = sum(encoded) / n
            variance = sum((x - mean) ** 2 for x in encoded) / (n - 1)
            std = math.sqrt(variance)
            if std == 0:
                result[col_name] = [0.0] * n
            else:
                result[col_name] = [(x - mean) / std for x in encoded]

    return result
