def column_histograms(table):
    if not isinstance(table, dict) or not table:
        raise ValueError("table must be a non-empty dict")

    num_bins = 10
    result = {}

    for col_name, values in table.items():
        if not values or not all(
            isinstance(v, numbers.Real) and not isinstance(v, bool)
            for v in values
        ):
            continue

        min_val = min(values)
        max_val = max(values)
        span = max_val - min_val

        counts = [0] * num_bins
        if span == 0:
            counts[0] = len(values)
        else:
            for v in values:
                idx = int(((v - min_val) / span) * num_bins)
                if idx >= num_bins:
                    idx = num_bins - 1
                counts[idx] += 1

        result[col_name] = counts

    if not result:
        raise ValueError("table must contain at least one numeric column")

    return result
