Here is an implementation of `summarize_distribution(values, bins)`:

```python
import math


def summarize_distribution(values, bins):
    if not values:
        raise ValueError("values must be a non-empty list of numbers")
    if not isinstance(bins, int) or bins <= 0:
        raise ValueError("bins must be a positive integer")

    n = len(values)
    mean = sum(values) / n

    sorted_vals = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        median = float(sorted_vals[mid])
    else:
        median = (sorted_vals[mid - 1] + sorted_vals[mid]) / 2.0

    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1

    mode = values[0]
    max_count = 0
    for v, count in counts.items():
        if count > max_count:
            max_count = count
            mode = v

    variance = sum((x - mean) ** 2 for x in values) / n
    std_dev = math.sqrt(variance)

    min_val = min(values)
    max_val = max(values)
    histogram = [0] * bins

    if min_val == max_val:
        histogram[0] = n
    else:
        span = max_val - min_val
        for x in values:
            if x == max_val:
                idx = bins - 1
            else:
                idx = int((x - min_val) * bins / span)
                idx = max(0, min(idx, bins - 1))
            histogram[idx] += 1

    return {
        "mean": mean,
        "median": median,
        "mode": mode,
        "std_dev": std_dev,
        "histogram": histogram,
    }
```

