```python
def normalize_columns(data_dict, data_keys):
    result = {}
    for key in data_keys:
        if key not in data_dict or key in result:
            continue
        values = data_dict[key]
        if not values:
            result[key] = []
            continue
        min_val = min(values)
        max_val = max(values)
        span = max_val - min_val
        if span == 0:
            result[key] = [0.0] * len(values)
        else:
            result[key] = [(x - min_val) / span for x in values]

    if not result:
        raise ValueError("None of the requested column names were found in data_dict.")

    return result
```

