```python
def course_grade_summary(records):
    stats = {}
    for _, course, grade in records:
        if course not in stats:
            stats[course] = [0.0, 0, 0]
        stats[course][0] += grade
        stats[course][1] += 1
        if grade >= 60:
            stats[course][2] += 1

    return {
        course: (total / count, passing_count)
        for course, (total, count, passing_count) in stats.items()
    }
```

