import io
import math


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    rows = []
    columns = None

    for text in csv_texts:
        reader = csv.DictReader(io.StringIO(text, newline=""))
        if reader.fieldnames is None:
            continue
        if columns is None:
            columns = list(reader.fieldnames)
        rows.extend(reader)

    if not rows or not columns:
        return []

    def parse_int(val):
        if "_" in val:
            raise ValueError("Underscores are not treated as numeric")
        return int(val)

    def parse_float(val):
        if "_" in val:
            raise ValueError("Underscores are not treated as numeric")
        num = float(val)
        if not math.isfinite(num):
            raise ValueError("Non-finite floats are not treated as numeric")
        return num

    converters = {}
    for col in columns:
        values = [row[col] for row in rows]
        try:
            for v in values:
                parse_int(v)
            converters[col] = parse_int
        except ValueError:
            try:
                for v in values:
                    parse_float(v)
                converters[col] = parse_float
            except ValueError:
                converters[col] = None

    result = []
    for row in rows:
        converted_row = {}
        for col in columns:
            val = row[col]
            conv = converters[col]
            converted_row[col] = conv(val) if conv is not None else val
        result.append(converted_row)

    return result
