To compute the mapped correlation matrix, you can replace values using the `mapping` dictionary and then calculate the pairwise Pearson correlation coefficients in pure Python:

```python
import math


def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    cols = list(data.keys())
    mapped = {
        col: [mapping[val] if val in mapping else val for val in data[col]]
        for col in cols
    }

    # Precompute means, centered values, and sums of squared deviations
    centered = {}
    sum_sq = {}
    for col in cols:
        values = mapped[col]
        n = len(values)
        if n == 0:
            centered[col] = []
            sum_sq[col] = 0.0
        else:
            mean = sum(values) / n
            diffs = [x - mean for x in values]
            centered[col] = diffs
            sum_sq[col] = sum(d * d for d in diffs)

    result = {col: {} for col in cols}
    for i, a in enumerate(cols):
        for j in range(i, len(cols)):
            b = cols[j]
            denom = math.sqrt(sum_sq[a] * sum_sq[b])
            if denom == 0.0:
                corr = float("nan")
            elif a == b:
                corr = 1.0
            else:
                num = sum(da * db for da, db in zip(centered[a], centered[b]))
                corr = max(-1.0, min(1.0, num / denom))

            result[a][b] = corr
            result[b][a] = corr

    return result
```

