def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    cols = list(data.keys())
    if not cols:
        return {}

    # Apply mapping to each column
    mapped = {
        col: [mapping.get(val, val) for val in values]
        for col, values in data.items()
    }

    # Precompute deviations from the mean and sum of squared deviations
    deviations = {}
    sq_sums = {}
    for col in cols:
        vals = mapped[col]
        n = len(vals)
        if n == 0:
            deviations[col] = []
            sq_sums[col] = 0.0
            continue
        mean = sum(vals) / n
        devs = [v - mean for v in vals]
        deviations[col] = devs
        sq_sums[col] = sum(d * d for d in devs)

    # Compute pairwise Pearson correlations
    result = {col: {} for col in cols}
    for i, a in enumerate(cols):
        for j in range(i, len(cols)):
            b = cols[j]
            denom = math.sqrt(sq_sums[a] * sq_sums[b])
            if denom == 0.0:
                corr = float("nan")
            elif a == b:
                corr = 1.0
            else:
                num = sum(da * db for da, db in zip(deviations[a], deviations[b]))
                corr = max(-1.0, min(1.0, num / denom))

            result[a][b] = corr
            result[b][a] = corr

    return result
