            denom = norms[a] * norms[b]
            if denom == 0.0:
                corr = float("nan")
            elif a == b:
                corr = 1.0
            else:
                cov = sum(x * y for x, y in zip(diffs[a], diffs[b]))
                corr = max(-1.0, min(1.0, cov / denom))
            result[a][b] = corr
            result[b][a] = corr

    return result
