# {'m': {'m': 1.0, 'n': 0.5}, 'n': {'m': 0.5, 'n': 1.0}}
```

### Notes
- Raises `ValueError` if `data` is not a `dict`.
- Replaces any value present as a key in `mapping` with `mapping[val]`, leaving all other values unchanged.
- Computes pairwise Pearson correlations symmetrically and clamps values to `[-1.0, 1.0]` to avoid floating-point drift (e.g. `1.0000000000000002`), returning `nan` if a column has zero variance.

Here is a pure-Python implementation of `mapped_correlation_matrix`:

```python
import math


def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    cols = list(data.keys())
    if not cols:
        return {}

    mapped = {
        col: [float(mapping[v] if v in mapping else v) for v in data[col]]
        for col in cols
    }

    deviations = {}
    norms = {}
    for col in cols:
        vals = mapped[col]
        n = len(vals)
        if n == 0:
            deviations[col] = []
            norms[col] = 0.0
        else:
            mean = sum(vals) / n
            devs = [x - mean for x in vals]
            deviations[col] = devs
            norms[col] = math.sqrt(sum(d * d for d in devs))

    result = {col: {} for col in cols}
    for i, a in enumerate(cols):
        for j in range(i, len(cols)):
            b = cols[j]
            denom = norms[a] * norms[b]
            if denom == 0.0:
                corr = float("nan")
            elif i == j:
                corr = 1.0
            else:
                num = sum(da * db for da, db in zip(deviations[a], deviations[b]))
                corr = max(-1.0, min(1.0, num / denom))
            result[a][b] = corr
            result[b][a] = corr

    return result
```

