Here is an implementation of `box_blur(image, kernel_size)`:

```python
def _reflect_index(index: int, length: int) -> int:
    if length == 1:
        return 0
    period = 2 * (length - 1)
    index %= period
    if index >= length:
        index = period - index
    return index


def _sliding_sum(values: list, kernel_size: int) -> list:
    if kernel_size == 1:
        return list(values)

    m = len(values)
    n = m - kernel_size + 1
    prefix = [0] * m
    suffix = [0] * m

    for start in range(0, m, kernel_size):
        end = min(start + kernel_size, m)
        running = 0
        for i in range(start, end):
            running += values[i]
            prefix[i] = running
        running = 0
        for i in range(end - 1, start - 1, -1):
            running += values[i]
            suffix[i] = running

    result = [0] * n
    for i in range(n):
        if i % kernel_size == 0:
            result[i] = suffix[i]
        else:
            result[i] = suffix[i] + prefix[i + kernel_size - 1]
    return result


def box_blur(image: list, kernel_size: int) -> list:
    if (
        isinstance(kernel_size, bool)
        or not isinstance(kernel_size, int)
        or kernel_size <= 0
        or kernel_size % 2 == 0
    ):
        raise ValueError("kernel_size must be a positive odd integer")

    height = len(image)
    if height == 0:
        return []
    width = len(image[0])
    if width == 0:
        return [[] for _ in range(height)]
    channels = len(image[0][0])
    if channels == 0:
        return [[[] for _ in range(width)] for _ in range(height)]

    half = kernel_size // 2
    area = kernel_size * kernel_size
    row_map = [_reflect_index(i - half, height) for i in range(height + kernel_size - 1)]
    col_map = [_reflect_index(i - half, width) for i in range(width + kernel_size - 1)]

    output = [[[0.0] * channels for _ in range(width)] for _ in range(height)]

    for ch in range(channels):
        horiz = [
            _sliding_sum([image[r][c][ch] for c in col_map], kernel_size)
            for r in range(height)
        ]
        for c in range(width):
            col_sums = _sliding_sum([horiz[r][c] for r in row_map], kernel_size)
            for r in range(height):
                output[r][c][ch] = col_sums[r] / area

    return output
```

### How it works
1. **Validation**: Checks that `kernel_size` is a positive odd `int` (excluding `bool`), raising `ValueError` otherwise.
2. **Mirror padding (`_reflect_index`)**: Maps out-of-bounds indices back into `[0, length - 1]` using reflection without repeating border pixels (a periodic triangle wave of period `2 * (length - 1)`), handling small images even when `kernel_size` exceeds the image dimensions.
3. **Separable box sum (`_sliding_sum`)**: Computes horizontal window sums followed by vertical window sums using block-wise prefix/suffix sums. This runs in $O(\text{height} \times \text{width} \times \text{channels})$ time regardless of `kernel_size`, avoids subtraction-based floating-point cancellation, and divides by `kernel_size ** 2` once at the end to return `float` values.

Here is a self-contained Python implementation using k-means++ initialization and Lloyd's algorithm (with multiple restarts to avoid poor local minima):

```python
import random


def cluster_centroids(points, k):
    """Group 2D points into k clusters with k-means and return sorted (x, y) float centroids."""
    if k < 0 or k > len(points):
        raise ValueError("k must be between 0 and the number of points.")
    if k == 0 or not points:
        return []

    pts = [(float(x), float(y)) for x, y in points]
    n = len(pts)
    if k == n:
        return sorted(pts)

    rng = random.Random(42)
    best_centroids = None
    best_inertia = float("inf")

    for _ in range(10):
        # k-means++ initialization
        centroids = [pts[rng.randrange(n)]]
        for _ in range(1, k):
            dists_sq = [
                min((px - cx) ** 2 + (py - cy) ** 2 for cx, cy in centroids)
                for px, py in pts
            ]
            total = sum(dists_sq)
            if total == 0:
                centroids.append(pts[rng.randrange(n)])
            else:
                r = rng.random() * total
                cumulative = 0.0
                for idx, d in enumerate(dists_sq):
                    cumulative += d
                    if cumulative >= r:
                        centroids.append(pts[idx])
                        break

        assignments = [-1] * n
        for _ in range(300):
            # Assignment step
            new_assignments = []
            for px, py in pts:
                best_c = min(
                    range(k),
                    key=lambda c: (px - centroids[c][0]) ** 2 + (py - centroids[c][1]) ** 2,
                )
                new_assignments.append(best_c)

            if new_assignments == assignments:
                break
            assignments = new_assignments

            # Update step
            sums_x = [0.0] * k
            sums_y = [0.0] * k
            counts = [0] * k
            for idx, c in enumerate(assignments):
                sums_x[c] += pts[idx][0]
                sums_y[c] += pts[idx][1]
                counts[c] += 1

            for c in range(k):
                if counts[c] > 0:
                    centroids[c] = (sums_x[c] / counts[c], sums_y[c] / counts[c])
                else:
                    # Handle empty cluster by picking the point farthest from its centroid
                    farthest_idx = max(
                        range(n),
                        key=lambda i: (
                            (pts[i][0] - centroids[assignments[i]][0]) ** 2
                            + (pts[i][1] - centroids[assignments[i]][1]) ** 2
                        ),
                    )
                    centroids[c] = pts[farthest_idx]

        inertia = sum(
            (pts[i][0] - centroids[assignments[i]][0]) ** 2
            + (pts[i][1] - centroids[assignments[i]][1]) ** 2
            for i in range(n)
        )
        if inertia < best_inertia:
            best_inertia = inertia
            best_centroids = centroids

    return sorted(best_centroids)
```

### Example usage
```python
print(cluster_centroids([[1, 1], [1, 2], [2, 1], [10, 10], [10, 11], [11, 10]], 2))
# [(1.3333333333333333, 1.3333333333333333), (10.333333333333334, 10.333333333333334)]
```

Here is a pure-Python implementation of `cluster_centroids(points, k)` using k-means with deterministic farthest-point initialization (to avoid poor local optima and ensure reproducible results):

```python
def cluster_centroids(points, k):
    if not points or k <= 0:
        return []

    pts = [(float(p[0]), float(p[1])) for p in points]
    if k >= len(pts):
        return sorted(pts)

    # Farthest-point initialization (deterministic)
    centroids = [min(pts)]
    for _ in range(1, k):
        farthest = max(
            pts,
            key=lambda p: min((p[0] - c[0]) ** 2 + (p[1] - c[1]) ** 2 for c in centroids),
        )
        centroids.append(farthest)

    max_iter = 300
    for _ in range(max_iter):
        clusters = [[] for _ in range(k)]

        # Assign each point to the nearest centroid
        for p in pts:
            nearest_idx = min(
                range(k),
                key=lambda i: (p[0] - centroids[i][0]) ** 2 + (p[1] - centroids[i][1]) ** 2,
            )
            clusters[nearest_idx].append(p)

        # Recompute centroids
        new_centroids = []
        for i, cluster in enumerate(clusters):
            if cluster:
                cx = sum(p[0] for p in cluster) / len(cluster)
                cy = sum(p[1] for p in cluster) / len(cluster)
                new_centroids.append((cx, cy))
            else:
                # Keep previous centroid if cluster is empty
                new_centroids.append(centroids[i])

        if all(
            abs(a[0] - b[0]) < 1e-12 and abs(a[1] - b[1]) < 1e-12
            for a, b in zip(centroids, new_centroids)
        ):
            centroids = new_centroids
            break

        centroids = new_centroids

    return sorted(centroids)
```

