points = [[1, 1], [1, 2], [2, 1], [10, 10], [10, 11], [11, 10]]
print(cluster_centroids(points, 2))
# Output: [(1.3333333333333333, 1.3333333333333333), (10.333333333333334, 10.333333333333334)]
```

You can use Python's built-in `html.parser.HTMLParser` to locate `<script>` elements in document order and `ast.literal_eval` to safely evaluate their contents as Python literals:

```python
import ast
from html.parser import HTMLParser


class _ScriptExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self._in_script = False
        self._chunks = []
        self.dicts = []

    def handle_starttag(self, tag, attrs):
        if tag == "script":
            self._in_script = True
            self._chunks = []

    def handle_data(self, data):
        if self._in_script:
            self._chunks.append(data)

    def handle_endtag(self, tag):
        if tag == "script" and self._in_script:
            self._in_script = False
            text = "".join(self._chunks).strip()
            self._chunks = []
            if text:
                try:
                    value = ast.literal_eval(text)
                except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
                    return
                if isinstance(value, dict):
                    self.dicts.append(value)


def extract_script_dicts(html: str) -> list[dict]:
    parser = _ScriptExtractor()
    parser.feed(html)
    parser.close()
    return parser.dicts
```

### How it works
- **`HTMLParser`**: Properly handles `<script>` tags (regardless of attributes or case) in raw-text mode, collecting all data chunks between `<script ...>` and `</script>` in document order.
- **`.strip()`**: Removes leading/trailing whitespace so indented multi-line script contents don't raise an `IndentationError` when parsed.
- **`ast.literal_eval`**: Safely parses Python literals without executing arbitrary code, and `isinstance(value, dict)` filters out non-dictionary literals (such as lists, sets, or strings).

You can implement `extract_script_dicts` using Python's built-in `html.parser.HTMLParser` to extract the raw text inside each `<script>` element in document order, and `ast.literal_eval` to safely parse Python dict literals:

```python
import ast
from html.parser import HTMLParser


class _ScriptExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self._in_script = False
        self._buffer = []
        self.scripts = []

    def handle_starttag(self, tag, attrs):
        if tag == "script":
            self._in_script = True
            self._buffer = []

    def handle_data(self, data):
        if self._in_script:
            self._buffer.append(data)

    def handle_endtag(self, tag):
        if tag == "script" and self._in_script:
            self.scripts.append("".join(self._buffer))
            self._in_script = False
            self._buffer = []


def extract_script_dicts(html: str) -> list[dict]:
    parser = _ScriptExtractor()
    parser.feed(html)
    parser.close()

    results = []
    for body in parser.scripts:
        text = body.strip()
        if not text:
            continue
        try:
            value = ast.literal_eval(text)
        except (ValueError, SyntaxError, TypeError, RecursionError):
            continue
        if isinstance(value, dict):
            results.append(value)

    return results
```

### How it works
- **HTML parsing**: `HTMLParser` treats `<script>` as a CDATA element, so inner strings like `"</foo>"` won't be parsed as tags, though `handle_data` may be called multiple times per `<script>`. Buffering chunks between `handle_starttag("script")` and `handle_endtag("script")` preserves the full script body.
- **Literal evaluation**: `ast.literal_eval(text)` safely evaluates Python literals without executing arbitrary code. Stripping whitespace prevents `IndentationError` on indented script blocks.
- **Filtering**: Non-dict literals (such as lists, sets, or numbers) and invalid Python syntax are skipped, returning only `dict` instances in document order.

To solve this, we can parse and validate `start_date` and `freq`, find the first matching date in the starting month/quarter (advancing to the next period if that date is earlier than `start_date`), and then generate one date per entry in `sales`.

Here is the implementation:

```python
import calendar
from datetime import date, datetime
import re


def forecast_schedule(start_date, freq, sales):
    if not isinstance(start_date, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", start_date):
        raise ValueError(f"Invalid start_date: {start_date!r}")
    try:
        start = datetime.strptime(start_date, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError(f"Invalid start_date: {start_date!r}") from exc

    weekdays = {
        "MON": 0,
        "TUE": 1,
        "WED": 2,
        "THU": 3,
        "FRI": 4,
        "SAT": 5,
        "SUN": 6,
    }

    if freq == "month-end":
        def date_for_period(year, month):
            last_day = calendar.monthrange(year, month)[1]
            return date(year, month, last_day)

        def next_period(year, month):
            return (year + 1, 1) if month == 12 else (year, month + 1)

        year, month = start.year, start.month

    elif freq == "quarter-end":
        def date_for_period(year, month):
            last_day = calendar.monthrange(year, month)[1]
            return date(year, month, last_day)

        def next_period(year, month):
            return (year + 1, 3) if month == 12 else (year, month + 3)

        year = start.year
        month = ((start.month - 1) // 3 + 1) * 3

    else:
        match = re.fullmatch(r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", freq) if isinstance(freq, str) else None
        if not match:
            raise ValueError(f"Invalid freq: {freq!r}")

        week_num = int(match.group(1))
        target_wd = weekdays[match.group(2)]

        def date_for_period(year, month):
            first_wd = date(year, month, 1).weekday()
            day = 1 + (target_wd - first_wd) % 7 + 7 * (week_num - 1)
            return date(year, month, day)

        def next_period(year, month):
            return (year + 1, 1) if month == 12 else (year, month + 1)

        year, month = start.year, start.month

    candidate = date_for_period(year, month)
    if candidate < start:
        year, month = next_period(year, month)
        candidate = date_for_period(year, month)

    schedule = []
    for value in sales:
        schedule.append((candidate.strftime("%Y-%m-%d"), value))
        year, month = next_period(year, month)
        candidate = date_for_period(year, month)

    return schedule
```

### Example Usage
```python
print(forecast_schedule("2021-01-01", "2-FRI", [272, 147, 217]))
# [('2021-01-08', 272), ('2021-02-12', 147), ('2021-03-12', 217)]

print(forecast_schedule("2021-01-31", "month-end", [100, 200]))
# [('2021-01-31', 100), ('2021-02-28', 200)]

print(forecast_schedule("2021-04-01", "quarter-end", [500, 600]))
# [('2021-06-30', 500), ('2021-09-30', 600)]
```

To compute the five-number summary with linear interpolation, you can use the standard `p * (n - 1)` index interpolation (equivalent to `numpy.percentile` with linear interpolation).

```python
import math


def country_score_summary(records):
    if not records:
        raise ValueError("records must not be empty")

    required_keys = ("Name", "Country", "Score")
    seen_names = set()
    scores_by_country = {}

    for record in records:
        if not isinstance(record, dict) or any(k not in record for k in required_keys):
            raise ValueError("Each record must be a dict containing 'Name', 'Country', and 'Score' keys")

        name = record["Name"]
        if name in seen_names:
            continue
        seen_names.add(name)

        country = record["Country"]
        scores_by_country.setdefault(country, []).append(record["Score"])

    def quantile(sorted_vals, p):
        n = len(sorted_vals)
        if n == 1:
            return float(sorted_vals[0])
        idx = p * (n - 1)
        lo = math.floor(idx)
        hi = math.ceil(idx)
        frac = idx - lo
        return float(sorted_vals[lo] + frac * (sorted_vals[hi] - sorted_vals[lo]))

    summary = {}
