To compute the sample covariance matrix, validate the table structure and element types, center each column by subtracting its mean, and divide the dot products of centered columns by `n - 1`:

```python
import numbers


def column_covariance(columns):
    if not columns:
        raise ValueError("Table cannot be empty (no columns).")

    col_names = list(columns.keys())
    lengths = {len(columns[name]) for name in col_names}
    if len(lengths) > 1:
        raise ValueError("All columns must have the same number of rows.")

    n = lengths.pop()
    if n == 0:
        raise ValueError("Table cannot be empty (no rows).")

    for name in col_names:
        for value in columns[name]:
            if isinstance(value, bool) or not isinstance(value, numbers.Real):
                raise TypeError(
                    f"Column {name!r} contains non-numeric value: {value!r}"
                )

    if n < 2:
        raise ValueError("At least two rows are required to compute sample covariance.")

    centered = {}
    for name in col_names:
        values = columns[name]
        mean = sum(values) / n
        centered[name] = [v - mean for v in values]

    result = {name: {} for name in col_names}
    for i, a in enumerate(col_names):
        ca = centered[a]
        for b in col_names[i:]:
            cb = centered[b]
            cov = sum(x * y for x, y in zip(ca, cb)) / (n - 1)
            result[a][b] = cov
            result[b][a] = cov

    return result
```

