Here is a pure-Python implementation of `cluster_point_indices(points, n_clusters)` using k-means++ initialization and multiple restarts to find a low-inertia clustering deterministically:

```python
import random


def cluster_point_indices(points, n_clusters):
    if not points or n_clusters <= 0:
        return []

    n_points = len(points)
    if n_clusters >= n_points:
        return [[i] for i in range(n_points)]

    dim = len(points[0])

    def sq_dist(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    def assign_points(centroids):
        labels = [0] * n_points
        dists = [0.0] * n_points
        for i, p in enumerate(points):
            best_c = 0
            best_d = sq_dist(p, centroids[0])
            for c in range(1, n_clusters):
                d = sq_dist(p, centroids[c])
                if d < best_d:
                    best_d = d
                    best_c = c
            labels[i] = best_c
            dists[i] = best_d
        return labels, dists

    def run_kmeans(seed):
        rng = random.Random(seed)

        # k-means++ initialization
        centroids = [list(points[rng.randrange(n_points)])]
        min_dists = [sq_dist(p, centroids[0]) for p in points]

        for _ in range(1, n_clusters):
            total = sum(min_dists)
            if total == 0:
                centroids.append(list(points[rng.randrange(n_points)]))
            else:
                threshold = rng.random() * total
                cumulative = 0.0
                chosen = n_points - 1
                for i, d in enumerate(min_dists):
                    cumulative += d
                    if cumulative >= threshold:
                        chosen = i
                        break
                centroids.append(list(points[chosen]))

            new_c = centroids[-1]
            for i, p in enumerate(points):
                d = sq_dist(p, new_c)
                if d < min_dists[i]:
                    min_dists[i] = d

        prev_labels = None
        for _ in range(300):
            labels, point_dists = assign_points(centroids)
            if labels == prev_labels:
                break
            prev_labels = labels

            sums = [[0.0] * dim for _ in range(n_clusters)]
            counts = [0] * n_clusters
            for i, p in enumerate(points):
                c = labels[i]
                counts[c] += 1
                for d_idx in range(dim):
                    sums[c][d_idx] += p[d_idx]

            for c in range(n_clusters):
                if counts[c] > 0:
                    centroids[c] = [s / counts[c] for s in sums[c]]
                else:
                    farthest_i = max(range(n_points), key=lambda idx: point_dists[idx])
                    centroids[c] = list(points[farthest_i])
                    point_dists[farthest_i] = 0.0
        else:
            labels, point_dists = assign_points(centroids)

        return labels, sum(point_dists)

    best_labels = None
    best_inertia = float("inf")
    for seed in range(10):
        labels, inertia = run_kmeans(seed)
        if inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels

    clusters = {}
    for idx, label in enumerate(best_labels):
        clusters.setdefault(label, []).append(idx)

    return sorted(clusters.values(), key=lambda c: c[0])
```

### Example

```python
>>> cluster_point_indices([[1, 1], [1.1, 1.1], [5, 5], [5.1, 5.1]], 2)
[[0, 1], [2, 3]]
```

### How it works
1. **Initialization**: Uses k-means++ over 10 fixed-seed restarts and selects the result with the lowest inertia (sum of squared distances to cluster centroids).
2. **Lloyd's algorithm**: Alternates between assigning points to their nearest centroid and updating centroids to cluster means, reinitializing any empty cluster to the point farthest from its centroid.
3. **Output ordering**: Iterating point indices in order (`0` to `len(points) - 1`) keeps indices within each cluster in ascending order, and `sorted(..., key=lambda c: c[0])` orders the clusters by their smallest index.

