from collections import Counter, defaultdict


def summarize_student_records(data):
    required_keys = ("Name", "Age", "Score")
    if any(key not in data for key in required_keys):
        raise ValueError("Input dict must contain 'Name', 'Age', and 'Score' keys.")

    records = [
        [name, age, score]
        for name, age, score in zip(data["Name"], data["Age"], data["Score"])
    ]

    # Python's sorted() is stable, so records with the same (name, age) keep their original order
    sorted_records = sorted(records, key=lambda r: (r[0], r[1]))

    scores_by_name = defaultdict(list)
    for name, _, score in sorted_records:
        scores_by_name[name].append(score)

    avg_scores = {
        name: sum(scores) / len(scores)
        for name, scores in scores_by_name.items()
    }

    most_common_age = (
        Counter(data["Age"]).most_common(1)[0][0] if sorted_records else None
    )

    return sorted_records, avg_scores, most_common_age
```

