    if value is None or "_" in value:
        return None
    try:
        num = float(value)
    except ValueError:
        return None
    return num if math.isfinite(num) else None


def sort_csv_rows(csv_text, sort_key):
    reader = csv.DictReader(io.StringIO(csv_text, newline=""))
    fieldnames = reader.fieldnames
    if not fieldnames or sort_key not in fieldnames:
        raise ValueError(f"Column {sort_key!r} does not exist in CSV.")

    rows = list(reader)
    if not rows:
        return []

    for col in fieldnames:
        values = [row[col] for row in rows]

        int_values = [_parse_int(v) for v in values]
        if all(v is not None for v in int_values):
            for row, num in zip(rows, int_values):
                row[col] = num
            continue

        float_values = [_parse_float(v) for v in values]
        if all(v is not None for v in float_values):
            for row, num in zip(rows, float_values):
                row[col] = num

    return sorted(rows, key=lambda row: row[sort_key])
```

### How it works:
- **CSV parsing**: Uses `csv.DictReader` over `io.StringIO(..., newline="")` so quoted values, embedded commas, and newlines are handled properly.
- **Column validation**: Checks `fieldnames` and raises `ValueError` if `sort_key` is missing (or if the CSV has no header).
- **Type conversion**: Checks each column—if every value parses as an `int`, converts the column to `int`; otherwise, if every value parses as a finite `float`, converts the column to `float` (ignoring underscores like `"1_2"` and non-finite strings like `"nan"` or `"inf"`). Otherwise, values stay as strings.
- **Stable sorting**: `sorted()` in Python uses Timsort, which preserves the original order of rows with equal sort keys.

