import json
import math


def numeric_correlation_from_json(json_text):
    """
    Compute the pairwise Pearson correlation matrix for numeric columns
    in a JSON object mapping column names to equal-length lists of values.
    """
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON input.") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("Data must be a non-empty JSON object.")

    lengths = set()
    for col, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"Column '{col}' must map to a list of values.")
        lengths.add(len(values))

    if len(lengths) > 1:
        raise ValueError("All columns must have equal length.")

    n = next(iter(lengths))
    if n == 0:
        raise ValueError("Data cannot be empty.")

    def is_numeric_column(values):
        return all(
            isinstance(v, (int, float))
            and not isinstance(v, bool)
            and math.isfinite(v)
            for v in values
        )

    numeric_cols = [
        col for col, values in data.items() if is_numeric_column(values)
    ]

    # Precompute centered vectors and sum of squares for each numeric column
    centered = {}
    sum_sq = {}
    for col in numeric_cols:
        vals = data[col]
        mean = sum(vals) / n
        diffs = [v - mean for v in vals]
        centered[col] = diffs
        sum_sq[col] = sum(d * d for d in diffs)

    matrix = {col: {} for col in numeric_cols}
    for i, col_i in enumerate(numeric_cols):
        for j in range(i, len(numeric_cols)):
            col_j = numeric_cols[j]
            denom = math.sqrt(sum_sq[col_i] * sum_sq[col_j])
            if denom == 0.0:
                corr = float("nan")
            elif i == j:
                corr = 1.0
            else:
                cov = sum(
                    a * b for a, b in zip(centered[col_i], centered[col_j])
                )
                corr = cov / denom
            matrix[col_i][col_j] = corr
            matrix[col_j][col_i] = corr

    return matrix
```

