import json
import math


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _pearson_corr(x, y):
    pairs = [(float(a), float(b)) for a, b in zip(x, y) if a is not None and b is not None]
    n = len(pairs)
    if n < 2:
        return float("nan")

    mean_x = sum(a for a, _ in pairs) / n
    mean_y = sum(b for _, b in pairs) / n
    dx = [a - mean_x for a, _ in pairs]
    dy = [b - mean_y for _, b in pairs]

    sum_sq_x = sum(a * a for a in dx)
    sum_sq_y = sum(b * b for b in dy)
    if sum_sq_x == 0.0 or sum_sq_y == 0.0:
        return float("nan")

    cov = sum(a * b for a, b in zip(dx, dy))
    r = cov / (math.sqrt(sum_sq_x) * math.sqrt(sum_sq_y))
    return max(-1.0, min(1.0, r))


def numeric_correlation_from_json(json_text):
    if not isinstance(json_text, str):
        raise ValueError("Input must be a JSON string.")

    try:
        data = json.loads(json_text)
    except json.JSONDecodeError as exc:
        raise ValueError("Invalid JSON.") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("Data must be a non-empty JSON object.")

    lengths = set()
    for col_name, values in data.items():
        if not isinstance(values, list):
            raise ValueError(f"Column {col_name!r} must map to a list.")
        lengths.add(len(values))

    if len(lengths) != 1 or next(iter(lengths)) == 0:
        raise ValueError("Columns must be non-empty lists of equal length.")

    numeric_cols = {
        col: vals
        for col, vals in data.items()
        if all(v is None or _is_number(v) for v in vals) and any(_is_number(v) for v in vals)
    }

    col_names = list(numeric_cols.keys())
    result = {col: {} for col in col_names}

    for i, c1 in enumerate(col_names):
        vals = [float(v) for v in numeric_cols[c1] if v is not None]
        if len(vals) < 2:
            result[c1][c1] = float("nan")
        else:
            mean_v = sum(vals) / len(vals)
            has_variance = sum((v - mean_v) ** 2 for v in vals) > 0.0
            result[c1][c1] = 1.0 if has_variance else float("nan")

        for j in range(i + 1, len(col_names)):
            c2 = col_names[j]
            corr = _pearson_corr(numeric_cols[c1], numeric_cols[c2])
            result[c1][c2] = corr
            result[c2][c1] = corr

    return result
```

