import csv
import io
import math


def correlation_matrix_from_csv(csv_text: str) -> dict[str, dict[str, float]]:
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]
    if not rows:
        return {}

    headers = rows[0]
    data_rows = rows[1:]
    n = len(data_rows)

    # Parse columns as floats
    columns = {h: [] for h in headers}
    for row in data_rows:
        for h, val in zip(headers, row):
            columns[h].append(float(val))

    # Precompute centered values and sum of squares for each column
    centered = {}
    sum_sq = {}
    for h in headers:
        vals = columns[h]
        if n == 0:
            centered[h] = []
            sum_sq[h] = 0.0
        else:
            mean = sum(vals) / n
            diffs = [x - mean for x in vals]
            centered[h] = diffs
            sum_sq[h] = sum(d * d for d in diffs)

    # Compute pairwise Pearson correlation
    result: dict[str, dict[str, float]] = {h: {} for h in headers}
    for i, a in enumerate(headers):
        for j in range(i, len(headers)):
            b = headers[j]
            if i == j:
                corr = 1.0 if sum_sq[a] > 0 else float("nan")
            else:
                denom = math.sqrt(sum_sq[a] * sum_sq[b])
                if denom == 0.0:
                    corr = float("nan")
                else:
                    cov = sum(x * y for x, y in zip(centered[a], centered[b]))
                    corr = cov / denom
            result[a][b] = corr
            result[b][a] = corr

    return result
```

