    n = len(data_rows)

    columns = {h: [] for h in headers}
    for row in data_rows:
        for h, val in zip(headers, row):
            columns[h].append(float(val))

    diffs = {}
    norms = {}
    for h in headers:
        vals = columns[h]
        if n == 0:
            diffs[h] = []
            norms[h] = 0.0
        else:
            mean = sum(vals) / n
            d = [x - mean for x in vals]
            diffs[h] = d
            norms[h] = math.sqrt(sum(x * x for x in d))

    result = {h: {} for h in headers}
    for i, a in enumerate(headers):
        for j in range(i, len(headers)):
            b = headers[j]
            if a == b:
                corr = 1.0 if norms[a] > 0 else float("nan")
            else:
                denom = norms[a] * norms[b]
                if denom == 0:
                    corr = float("nan")
                else:
                    num = sum(x * y for x, y in zip(diffs[a], diffs[b]))
                    corr = max(-1.0, min(1.0, num / denom))
            result[a][b] = corr
            result[b][a] = corr

    return result
```

### How it works
1. **Parsing:** `csv.reader` reads `csv_text` via `io.StringIO`, ignoring blank lines, extracting the header row, and converting each column's values to `float`.
2. **Centering & Norms:** For each column, it computes the mean-centered values $x_i - \bar{x}$ and the Euclidean norm $\sqrt{\sum (x_i - \bar{x})^2}$.
3. **Pairwise Correlation:** Since the correlation matrix is symmetric, it computes each upper-triangular pair `(a, b)` once using the Pearson formula $\frac{\sum (x_i - \bar{x})(y_i - \bar{y})}{\sqrt{\sum (x_i - \bar{x})^2} \sqrt{\sum (y_i - \bar{y})^2}}$ (clamping to `[-1.0, 1.0]` to guard against floating-point overshoot) and returns `NaN` for constant or empty columns where the variance is zero.

Here is a pure-Python implementation using only the standard library (`random`). It standardizes each column to zero mean and unit variance, runs k-means (using k-means++ initialization across multiple restarts to avoid poor local minima), and relabels the resulting clusters in order of first appearance.

```python
import random


def cluster_labels(rows):
    n = len(rows)
    if n == 0:
        return []
    m = len(rows[0])
    k = min(3, n)

    # 1. Standardize each column to zero mean and unit variance
    standardized = [[0.0] * m for _ in range(n)]
    for j in range(m):
        col = [rows[i][j] for i in range(n)]
        mean = sum(col) / n
        var = sum((x - mean) ** 2 for x in col) / n
        std = var ** 0.5
        if std > 0:
            for i in range(n):
                standardized[i][j] = (col[i] - mean) / std

    def sq_dist(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # 2. Run k-means with k-means++ initialization and multiple restarts
    rng = random.Random(42)
    best_labels = None
    best_inertia = float("inf")

    for _ in range(10):
        # k-means++ initialization
        centroids = [list(standardized[rng.randrange(n)])]
        for _ in range(1, k):
            d2 = [min(sq_dist(p, c) for c in centroids) for p in standardized]
            total = sum(d2)
            if total == 0:
                centroids.append(list(standardized[rng.randrange(n)]))
            else:
                target = rng.uniform(0.0, total)
                cumulative = 0.0
                chosen = n - 1
                for i, w in enumerate(d2):
                    cumulative += w
                    if cumulative >= target:
                        chosen = i
                        break
                centroids.append(list(standardized[chosen]))

        labels = [-1] * n
        for _ in range(300):
            # Assignment step
            new_labels = [
                min(range(k), key=lambda c: sq_dist(standardized[i], centroids[c]))
                for i in range(n)
            ]
            if new_labels == labels:
                break
            labels = new_labels

            # Update step
            counts = [0] * k
            sums = [[0.0] * m for _ in range(k)]
            for i, c in enumerate(labels):
                counts[c] += 1
                for j in range(m):
                    sums[c][j] += standardized[i][j]

            for c in range(k):
                if counts[c] > 0:
                    centroids[c] = [sums[c][j] / counts[c] for j in range(m)]
                else:
                    # Re-seed empty cluster to the point farthest from its centroid
                    farthest = max(
                        range(n),
                        key=lambda i: sq_dist(standardized[i], centroids[labels[i]]),
                    )
                    centroids[c] = list(standardized[farthest])

        inertia = sum(sq_dist(standardized[i], centroids[labels[i]]) for i in range(n))
        if inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels

    # 3. Renumber clusters 0, 1, 2 in order of first appearance
    mapping = {}
    result = []
    for label in best_labels:
        if label not in mapping:
            mapping[label] = len(mapping)
        result.append(mapping[label])

    return result
```

