```python
import math
import random


def cluster_labels(rows, k=3, max_iter=100, n_init=10):
    if not rows:
        return []
    n_rows = len(rows)
    n_cols = len(rows[0])
    if n_rows <= k:
        return list(range(n_rows))

    # 1. Standardize each column to zero mean and unit variance
    standardized = [[0.0] * n_cols for _ in range(n_rows)]
    for j in range(n_cols):
        col = [rows[i][j] for i in range(n_rows)]
        mean = sum(col) / n_rows
        var = sum((x - mean) ** 2 for x in col) / n_rows
        std = math.sqrt(var)
        if std > 0.0:
            for i in range(n_rows):
                standardized[i][j] = (col[i] - mean) / std

    def sq_dist(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    def run_kmeans(rng):
        # k-means++ initialization
        centers = [standardized[rng.randrange(n_rows)][:] ]
        for _ in range(1, k):
            dists = [min(sq_dist(row, c) for c in centers) for row in standardized]
            total = sum(dists)
            if total == 0.0:
                centers.append(standardized[rng.randrange(n_rows)][:])
            else:
                r = rng.random() * total
                cumulative = 0.0
                chosen = n_rows - 1
                for idx, d in enumerate(dists):
                    cumulative += d
                    if cumulative >= r:
                        chosen = idx
                        break
                centers.append(standardized[chosen][:])

        labels = [0] * n_rows
        for _ in range(max_iter):
            changed = False
            # Assignment step
            for i, row in enumerate(standardized):
                best_c = min(range(k), key=lambda c: sq_dist(row, centers[c]))
                if labels[i] != best_c:
                    labels[i] = best_c
                    changed = True

            if not changed:
                break

            # Update step
            sums = [[0.0] * n_cols for _ in range(k)]
            counts = [0] * k
            for row, label in zip(standardized, labels):
                counts[label] += 1
                for j in range(n_cols):
                    sums[label][j] += row[j]

            for c in range(k):
                if counts[c] > 0:
                    centers[c] = [sums[c][j] / counts[c] for j in range(n_cols)]
                else:
                    # Re-seed empty cluster to the point farthest from its assigned center
                    farthest = max(
                        range(n_rows),
                        key=lambda i: sq_dist(standardized[i], centers[labels[i]]),
                    )
                    centers[c] = standardized[farthest][:]

        inertia = sum(sq_dist(standardized[i], centers[labels[i]]) for i in range(n_rows))
        return inertia, labels

    # 2. Run multiple deterministic restarts and keep the lowest-inertia clustering
    rng = random.Random(42)
    best_labels = min((run_kmeans(rng) for _ in range(n_init)), key=lambda x: x[0])[1]

    # 3. Relabel clusters 0, 1, 2 in order of first appearance
    mapping = {}
    result = []
    for label in best_labels:
        if label not in mapping:
            mapping[label] = len(mapping)
        result.append(mapping[label])
    return result
```

