from collections import Counter


def column_summary_stats(table, mapping, features):
    result = {}

    for feature in features:
        if feature not in table:
            raise ValueError(f"Feature '{feature}' not found in table.")

        values = [mapping.get(v, v) for v in table[feature]]
        n = len(values)
        if n == 0:
            raise ValueError(f"Feature '{feature}' has no values.")

        mean = sum(values) / n

        sorted_vals = sorted(values)
        mid = n // 2
        if n % 2 == 1:
            median = float(sorted_vals[mid])
        else:
            median = (sorted_vals[mid - 1] + sorted_vals[mid]) / 2.0

        counts = Counter(values)
        max_count = max(counts.values())
        mode = min(val for val, count in counts.items() if count == max_count)

        variance = sum((x - mean) ** 2 for x in values) / n

        result[feature] = {
            'mean': mean,
            'median': median,
            'mode': mode,
            'variance': variance,
        }

    return result
```

