- **Validation**: Raises `ValueError` if no `<table>` exists or if the first table contains no `<td>` rows.

Here is an implementation using Python's built-in `html.parser.HTMLParser`:

```python
from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found_table = False
        self.done = False
        self.table_depth = 0
        self.in_tr = False
        self.cell_type = None
        self.cell_parts = []
        self.current_tds = []
        self.headers = []
        self.rows = []

    def _close_cell(self):
        if self.cell_type is not None:
            text = "".join(self.cell_parts).strip()
            if self.cell_type == "th":
                self.headers.append(text)
            elif self.cell_type == "td":
                self.current_tds.append(text)
            self.cell_type = None
            self.cell_parts = []

    def _close_row(self):
        self._close_cell()
        if self.in_tr:
            if self.current_tds:
                self.rows.append(self.current_tds)
            self.current_tds = []
            self.in_tr = False

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        if tag == "table":
            if not self.found_table:
                self.found_table = True
                self.table_depth = 1
            else:
                self.table_depth += 1
            return

        if self.table_depth != 1:
            return

        if tag == "tr":
            self._close_row()
            self.in_tr = True
            self.current_tds = []
        elif tag in ("th", "td"):
            if not self.in_tr:
                self.in_tr = True
                self.current_tds = []
            self._close_cell()
            self.cell_type = tag
            self.cell_parts = []

    def handle_endtag(self, tag):
        if self.done or self.table_depth == 0:
            return

        if tag == "table":
            if self.table_depth == 1:
                self._close_row()
                self.table_depth = 0
                self.done = True
            else:
                self.table_depth -= 1
            return

        if self.table_depth != 1:
            return

        if tag == "tr":
            self._close_row()
        elif tag in ("th", "td") and self.cell_type == tag:
            self._close_cell()

    def handle_data(self, data):
        if not self.done and self.table_depth >= 1 and self.cell_type is not None:
            self.cell_parts.append(data)

    def finalize(self):
        if self.found_table and not self.done:
            self._close_row()
            self.done = True


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()
    parser.finalize()

    if not parser.found_table or not parser.rows:
        raise ValueError("No table or no data rows found in HTML.")

    return parser.headers, parser.rows
```

### How it works
- **First table isolation**: Tracks `table_depth` so only the first `<table>` is parsed and any subsequent or nested `<table>` tags do not add extra rows/headers.
- **Tag stripping & entity decoding**: `HTMLParser(..., convert_charrefs=True)` automatically decodes HTML entities and character references, while `handle_data` collects only text nodes inside `<th>` and `<td>` cells (ignoring inner formatting tags and comments) and `.strip()` removes surrounding whitespace.
- **Row & header handling**: Collects every `<th>` into `headers` and records every `<tr>` containing at least one `<td>` into `rows` in document order, skipping header-only rows. Also handles omitted closing tags cleanly.
- **Validation**: Raises `ValueError` if no `<table>` is found or if `rows` is empty.

