import math


def integer_histogram_counts(data_str, separator=',', bins=20):
    if not data_str or not data_str.strip():
        raise ValueError("Input string cannot be empty.")
    if bins <= 0:
        raise ValueError("Number of bins must be positive.")

    values = []
    for raw_token in data_str.split(separator):
        token = raw_token.strip()
        if not token:
            raise ValueError("Empty value encountered in input string.")
        try:
            val = int(token)
        except ValueError:
            try:
                f_val = float(token)
            except ValueError as exc:
                raise ValueError(f"Non-numeric value: {token!r}") from exc
            if not math.isfinite(f_val):
                raise ValueError(f"Non-finite value: {token!r}")
            val = int(f_val)
        values.append(val)

    min_val = min(values)
    max_val = max(values)
    span = max_val - min_val

    counts = [0] * bins
    if span == 0:
        counts[-1] = len(values)
    else:
        for val in values:
            idx = ((val - min_val) * bins) // span
            if idx >= bins:
                idx = bins - 1
            counts[idx] += 1

    return values, counts
