    for col in fieldnames:
        parsed_values = [_parse_number(row[col]) for row in rows]
        if all(val is not None for val in parsed_values):
            for row, val in zip(rows, parsed_values):
                row[col] = val

    return sorted(rows, key=lambda row: row[sort_by_column])
