Here is an implementation of `grayscale_histogram(data)` that handles both binary (`P5`) and ASCII (`P2`) 8-bit PGM images, including header/ASCII-raster comments and full validation:

```python
from collections import Counter
import re

_WHITESPACE = frozenset(b" \t\r\n\v\f")
_COMMENT_RE = re.compile(b"#[^\r\n]*")


def _skip_ws_and_comments(data: bytes, pos: int) -> int:
    n = len(data)
    while pos < n:
        b = data[pos]
        if b in _WHITESPACE:
            pos += 1
        elif b == 35:  # b'#'
            nl = data.find(b"\n", pos + 1)
            cr = data.find(b"\r", pos + 1)
            if nl == -1 and cr == -1:
                return n
            if nl == -1:
                pos = cr + 1
            elif cr == -1:
                pos = nl + 1
            else:
                pos = min(nl, cr) + 1
        else:
            break
    return pos


def _read_header_uint(data: bytes, pos: int) -> tuple[int, int]:
    pos = _skip_ws_and_comments(data, pos)
    n = len(data)
    start = pos
    while pos < n and 48 <= data[pos] <= 57:  # ASCII '0'-'9'
        pos += 1
    if pos == start:
        raise ValueError("Expected unsigned integer in PGM header")
    return int(data[start:pos]), pos


def grayscale_histogram(data: bytes) -> dict[int, int]:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise ValueError("Input must be bytes-like")
    if not isinstance(data, bytes):
        data = bytes(data)

    n = len(data)
    if n < 2:
        raise ValueError("Invalid PGM header: data too short")

    magic = data[:2]
    if magic not in (b"P2", b"P5"):
        raise ValueError("Invalid PGM magic number")

    pos = 2
    if pos >= n or (data[pos] not in _WHITESPACE and data[pos] != 35):
        raise ValueError("Missing whitespace after PGM magic number")

    width, pos = _read_header_uint(data, pos)
    height, pos = _read_header_uint(data, pos)
    maxval, pos = _read_header_uint(data, pos)

    if width <= 0 or height <= 0:
        raise ValueError("PGM dimensions must be positive")
    if not (1 <= maxval <= 255):
        raise ValueError("PGM maxval must be between 1 and 255 for 8-bit grayscale")

    expected_pixels = width * height

    if magic == b"P5":
        # P5 raster begins immediately after a single whitespace byte
        if pos >= n or data[pos] not in _WHITESPACE:
            raise ValueError("Missing single whitespace character after maxval")
        pos += 1

        if n - pos != expected_pixels:
            raise ValueError("P5 raster size does not match width * height")

        hist = dict(Counter(memoryview(data)[pos:]))
        if hist and max(hist) > maxval:
            raise ValueError("Pixel value exceeds maxval")
        return hist

    # P2 (ASCII)
    if pos >= n or (data[pos] not in _WHITESPACE and data[pos] != 35):
        raise ValueError("Missing whitespace after maxval")

    raster = data[pos:]
    if b"#" in raster:
        raster = _COMMENT_RE.sub(b" ", raster)

    tokens = raster.split()
    if len(tokens) != expected_pixels:
        raise ValueError("P2 pixel count does not match width * height")

    hist: dict[int, int] = {}
    for tok, count in Counter(tokens).items():
        if not tok.isdigit():
            raise ValueError("Invalid pixel value in P2 raster")
        val = int(tok)
        if val > maxval:
            raise ValueError("Pixel value exceeds maxval")
        hist[val] = hist.get(val, 0) + count

    return hist
```

### Key behaviors
- **Header parsing**: Validates magic number (`P2` or `P5`), supports `# ...` comments in the header, and requires positive `width`/`height` and `1 <= maxval <= 255`.
- **Binary (`P5`)**: Consumes the single whitespace delimiter after `maxval`, checks that the remaining byte count equals `width * height`, and verifies no byte exceeds `maxval`.
- **ASCII (`P2`)**: Strips `# ...` comments in the raster, checks that the token count equals `width * height`, ensures every token consists strictly of ASCII digits (`tok.isdigit()` rejects `+`/`-`/`_`), and verifies all values are `<= maxval`.
- **Output**: Returns a plain `dict` containing only pixel values that appear at least once.

