import re

_WHITESPACE = frozenset(b" \t\r\n\v\f")
_COMMENT_RE = re.compile(rb"#[^\r\n]*")


def _skip_ws_and_comments(data: bytes, pos: int) -> int:
    n = len(data)
    while pos < n:
        byte = data[pos]
        if byte in _WHITESPACE:
            pos += 1
        elif byte == 35:  # '#'
            pos += 1
            while pos < n and data[pos] not in (10, 13):  # '\n', '\r'
                pos += 1
        else:
            break
    return pos


def _read_header_int(data: bytes, pos: int) -> tuple[int, int]:
    pos = _skip_ws_and_comments(data, pos)
    n = len(data)
    start = pos
    while pos < n and 48 <= data[pos] <= 57:  # '0'..'9'
        pos += 1
    if pos == start:
        raise ValueError("Expected integer in PGM header")
    return int(data[start:pos]), pos


def grayscale_histogram(data: bytes) -> dict[int, int]:
