        raise ValueError("Input must be bytes-like")
    if isinstance(data, memoryview):
        data = data.tobytes()

    n = len(data)
    if n < 2:
        raise ValueError("Invalid PGM header")

    magic = data[:2]
    if magic not in (b"P2", b"P5"):
        raise ValueError(f"Unsupported or invalid PGM magic number: {magic!r}")

    if n == 2 or (data[2] not in _WHITESPACE and data[2] != 35):
        raise ValueError("Magic number must be followed by whitespace or comment")

    pos = 2
    width, pos = _read_header_int(data, pos)
    height, pos = _read_header_int(data, pos)
    maxval, pos = _read_header_int(data, pos)

    if width <= 0 or height <= 0:
        raise ValueError("Image dimensions must be positive")
    if not (1 <= maxval <= 255):
        raise ValueError("8-bit PGM maxval must be between 1 and 255")

    expected_pixels = width * height

    if pos >= n:
        raise ValueError("Unexpected end of file after PGM header")

    if magic == b"P5":
        # Binary PGM has a single whitespace byte (or comment ending in CR/LF)
        # immediately preceding the raw pixel bytes.
        if data[pos] in _WHITESPACE:
            pos += 1
        elif data[pos] == 35:  # '#'
            pos += 1
            while pos < n and data[pos] not in (10, 13):
                pos += 1
            if pos >= n:
                raise ValueError("Unexpected end of file in header comment")
            pos += 1
        else:
            raise ValueError("Invalid delimiter after maxval")

        raster = data[pos:]
        if len(raster) != expected_pixels:
            raise ValueError(
                f"Expected {expected_pixels} pixel bytes, got {len(raster)}"
            )

        counts = dict(Counter(raster))
        if any(val > maxval for val in counts):
            raise ValueError("Pixel value exceeds maxval")
        return counts

    # P2 (ASCII)
    if data[pos] not in _WHITESPACE and data[pos] != 35:
        raise ValueError("Invalid delimiter after maxval")

    cleaned = _COMMENT_RE.sub(b" ", data[pos:])
    tokens = cleaned.split()
    if len(tokens) != expected_pixels:
        raise ValueError(
            f"Expected {expected_pixels} pixel values, got {len(tokens)}"
        )

    counts: dict[int, int] = {}
    for tok in tokens:
        if not tok.isdigit():
            raise ValueError(f"Invalid pixel value: {tok!r}")
        val = int(tok)
        if val > maxval:
            raise ValueError(f"Pixel value {val} exceeds maxval {maxval}")
        counts[val] = counts.get(val, 0) + 1

    return counts
