def classical_seasonal_decomposition(values, period, model='additive'):
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or period < 1:
        raise ValueError("period must be a positive integer")

    vals = [float(v) for v in values]
    n = len(vals)
    if n < 2 * period:
        raise ValueError("values must be at least two full periods long")

    half = period // 2
    trend = [None] * n

    if period % 2 == 1:
        for i in range(half, n - half):
            trend[i] = sum(vals[i - half : i + half + 1]) / period
    else:
        for i in range(half, n - half):
            window = vals[i - half : i + half + 1]
            trend[i] = (0.5 * window[0] + sum(window[1:-1]) + 0.5 * window[-1]) / period

    phase_sums = [0.0] * period
    phase_counts = [0] * period
    for i in range(n):
        if trend[i] is not None:
            detrended = vals[i] - trend[i] if model == 'additive' else vals[i] / trend[i]
            phase = i % period
            phase_sums[phase] += detrended
            phase_counts[phase] += 1

    phase_avgs = [s / c for s, c in zip(phase_sums, phase_counts)]
    avg_of_phases = sum(phase_avgs) / period

    if model == 'additive':
        period_seasonal = [p - avg_of_phases for p in phase_avgs]
    else:
        period_seasonal = [p / avg_of_phases for p in phase_avgs]

    seasonal = [period_seasonal[i % period] for i in range(n)]

    resid = [None] * n
    for i in range(n):
        if trend[i] is not None:
            if model == 'additive':
                resid[i] = vals[i] - trend[i] - seasonal[i]
            else:
                resid[i] = vals[i] / (trend[i] * seasonal[i])

    return {
        'trend': trend,
        'seasonal': seasonal,
        'resid': resid,
    }
