        for i in range(half, n - half):
            trend[i] = sum(series[i - half : i + half + 1]) / period
    else:
        for i in range(half, n - half):
            weighted_sum = (
                0.5 * series[i - half]
                + sum(series[i - half + 1 : i + half])
                + 0.5 * series[i + half]
            )
            trend[i] = weighted_sum / period

    buckets = [[] for _ in range(period)]
    for i in range(half, n - half):
        if model == 'additive':
            detrended = series[i] - trend[i]
        else:
            if trend[i] == 0:
                raise ValueError("Multiplicative decomposition requires non-zero trend values")
