    period_averages = [sum(b) / len(b) for b in buckets]
    mean_avg = sum(period_averages) / period

    if model == 'additive':
        seasonal_pattern = [avg - mean_avg for avg in period_averages]
    else:
        if mean_avg == 0:
            raise ValueError("Multiplicative decomposition requires non-zero mean seasonal factor")
        seasonal_pattern = [avg / mean_avg for avg in period_averages]

    seasonal = [seasonal_pattern[i % period] for i in range(n)]

    resid = [None] * n
    for i in range(half, n - half):
        if model == 'additive':
            resid[i] = series[i] - trend[i] - seasonal[i]
        else:
            if seasonal[i] == 0:
                raise ValueError("Multiplicative decomposition requires non-zero seasonal factors")
            resid[i] = series[i] / (trend[i] * seasonal[i])

