import csv
import io
import math
import re


_THOUSANDS_RE = re.compile(r"^[+-]?\d{1,3}(,\d{3})+(\.\d*)?$")


def _parse_number(value: str) -> float | None:
    s = value.strip()
    if not s:
        return None
    if "," in s:
        if not _THOUSANDS_RE.fullmatch(s):
            return None
        s = s.replace(",", "")
    try:
        num = float(s)
    except ValueError:
        return None
    return num if math.isfinite(num) else None


def summarize_numeric_csv(csv_text: str) -> dict:
    reader = csv.reader(io.StringIO(csv_text))
    rows = [row for row in reader if row]
    if len(rows) < 2:
        return {"means": {}, "std_devs": {}, "f_value": None}

    headers = rows[0]
    data_rows = rows[1:]
    num_cols = len(headers)

    numeric_columns: dict[str, list[float]] = {}
    for col_idx, name in enumerate(headers):
        values: list[float] = []
        valid = True
        for row in data_rows:
            if col_idx >= len(row):
                valid = False
                break
            parsed = _parse_number(row[col_idx])
            if parsed is None:
                valid = False
                break
            values.append(parsed)
        if valid and len(values) >= 2:
            numeric_columns[name] = values

    means: dict[str, float] = {}
    std_devs: dict[str, float] = {}
    for name, values in numeric_columns.items():
        n = len(values)
        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / (n - 1)
        means[name] = mean
        std_devs[name] = math.sqrt(variance)

    f_value: float | None = None
    k = len(numeric_columns)
    if k >= 2:
        total_n = sum(len(vals) for vals in numeric_columns.values())
        grand_mean = sum(sum(vals) for vals in numeric_columns.values()) / total_n

        ss_between = sum(
            len(vals) * (means[name] - grand_mean) ** 2
            for name, vals in numeric_columns.items()
        )
        ss_within = sum(
            sum((x - means[name]) ** 2 for x in vals)
            for name, vals in numeric_columns.items()
        )

        df_between = k - 1
        df_within = total_n - k
        if df_within > 0 and ss_within > 0:
            ms_between = ss_between / df_between
            ms_within = ss_within / df_within
            f_value = ms_between / ms_within

    return {
        "means": means,
        "std_devs": std_devs,
        "f_value": f_value,
    }
```

### How it works
1. **CSV parsing & number validation**: Uses `csv.reader` so quoted values containing thousands separators (e.g., `"1,000"`, `"-12,345.67"`) are read properly. Each cell is parsed via `_parse_number`, which validates comma-separated thousands formatting and rejects non-numeric or non-finite values. Any column with an invalid or missing cell is excluded.
2. **Summary statistics**: Computes the arithmetic mean and sample standard deviation ($n - 1$ denominator) for each valid numeric column.
3. **One-way ANOVA**: If at least two numeric columns exist, computes the between-group sum of squares ($SS_B$) and within-group sum of squares ($SS_W$) across the columns as groups, then returns $F = \frac{SS_B / (k - 1)}{SS_W / (N - k)}$ (or `None` if fewer than two numeric columns remain).

