        k = len(groups)
        total_n = sum(len(g) for g in groups)
        grand_mean = sum(sum(g) for g in groups) / total_n

        ss_between = sum(
            len(g) * (means[name] - grand_mean) ** 2
            for name, g in numeric_columns.items()
