Here is an implementation of `standardize_and_correlate(table)` using Python's standard library:

```python
import math


def standardize_and_correlate(table):
    if not table:
        raise ValueError("Table is empty.")

    lengths = {len(col) for col in table.values()}
    if len(lengths) != 1:
        raise ValueError("All columns must have equal length.")

    n = next(iter(lengths))
    if n == 0:
        raise ValueError("Table has no rows.")

    standardized = {}
    numeric_cols = []

    for name, col in table.items():
        if all(isinstance(x, (int, float)) and not isinstance(x, bool) for x in col):
            mean = sum(col) / n
            variance = sum((x - mean) ** 2 for x in col) / n
            std = math.sqrt(variance)
            if std == 0:
                raise ValueError(f"Numeric column '{name}' has zero standard deviation.")
            z_col = [(x - mean) / std for x in col]
            standardized[name] = z_col
            numeric_cols.append(z_col)
        else:
            standardized[name] = list(col)

    if not numeric_cols:
        raise ValueError("Table has no numeric columns.")

    k = len(numeric_cols)
    corr = [[0.0] * k for _ in range(k)]
    for i in range(k):
        corr[i][i] = 1.0
        for j in range(i + 1, k):
            r = sum(a * b for a, b in zip(numeric_cols[i], numeric_cols[j])) / n
            r = max(-1.0, min(1.0, r))
            corr[i][j] = r
            corr[j][i] = r

    return standardized, corr
```

### How it works
1. **Validation**: Raises `ValueError` if `table` is empty, has zero-length columns, has mismatched column lengths, or contains no numeric columns (explicitly excluding `bool`, since `bool` is a subclass of `int` in Python).
2. **Standardization**: Preserves dictionary insertion order. Numeric columns are transformed using the population mean and population standard deviation ($\sqrt{\frac{1}{n}\sum (x_i - \mu)^2}$). Non-numeric columns are copied unchanged.
3. **Correlation matrix**: Because each numeric column is already standardized to mean `0` and population standard deviation `1`, the Pearson correlation between two numeric columns simplifies to the mean of their element-wise products: $\frac{1}{n}\sum z_{i,a} z_{i,b}$. Diagonal entries are set directly to `1.0`, and off-diagonal entries are mirrored and clamped to `[-1.0, 1.0]` to guard against minor floating-point drift.

Here is the implementation of `standardize_and_correlate`:

```python
import math


def standardize_and_correlate(table):
    if not table:
        raise ValueError("Table is empty.")

    lengths = {len(col) for col in table.values()}
    if len(lengths) != 1:
        raise ValueError("All columns must have equal length.")

    n = next(iter(lengths))
    if n == 0:
        raise ValueError("Table has no rows.")

    def is_numeric_column(col):
        return all(isinstance(v, (int, float)) and not isinstance(v, bool) for v in col)

    standardized = {}
    numeric_cols = []

    for name, col in table.items():
        if is_numeric_column(col):
            mean = sum(col) / n
            variance = sum((x - mean) ** 2 for x in col) / n
            std = math.sqrt(variance)
            if std == 0:
                raise ValueError(f"Numeric column '{name}' has zero standard deviation.")
            z = [(x - mean) / std for x in col]
            standardized[name] = z
            numeric_cols.append(z)
        else:
            standardized[name] = list(col)

    if not numeric_cols:
        raise ValueError("Table has no numeric columns.")

    k = len(numeric_cols)
    corr = [[0.0] * k for _ in range(k)]
    for i in range(k):
        corr[i][i] = 1.0
        for j in range(i + 1, k):
            r = sum(a * b for a, b in zip(numeric_cols[i], numeric_cols[j])) / n
            corr[i][j] = r
            corr[j][i] = r

    return standardized, corr
