import json
import math
from collections import defaultdict


def _quantile(sorted_vals, p):
    n = len(sorted_vals)
    if n == 1:
        return float(sorted_vals[0])
    pos = p * (n - 1)
    lo = math.floor(pos)
    hi = math.ceil(pos)
    if lo == hi:
        return float(sorted_vals[lo])
    frac = pos - lo
    return float(sorted_vals[lo] + frac * (sorted_vals[hi] - sorted_vals[lo]))


def summarize_values_by_key(json_text):
    if not isinstance(json_text, (str, bytes, bytearray)):
        raise ValueError("Input must be a JSON string.")

    try:
        data = json.loads(json_text)
    except json.JSONDecodeError as exc:
        raise ValueError("Invalid JSON input.") from exc

    if not isinstance(data, list):
        raise ValueError("JSON root must be a list of objects.")

    values_by_key = defaultdict(list)
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each element in the list must be a JSON object.")
        for key, value in item.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"Value for key {key!r} must be a number.")
            values_by_key[key].append(value)

    summary = {}
    for key, vals in values_by_key.items():
        sorted_vals = sorted(vals)
        summary[key] = {
            "mean": float(sum(sorted_vals) / len(sorted_vals)),
            "median": _quantile(sorted_vals, 0.5),
            "q1": _quantile(sorted_vals, 0.25),
            "q3": _quantile(sorted_vals, 0.75),
        }

    return summary
```

### How it works:
1. **Parsing & validation**: `json.loads` parses the string and converts any `JSONDecodeError` (or invalid structure/non-numeric values) into a `ValueError`.
2. **Grouping**: Collects values per key across all objects, ignoring objects where a key is absent.
3. **Linear interpolation quartiles**: Computes the index `p * (n - 1)` on the sorted values (`p` = `0.25`, `0.5`, `0.75`) and linearly interpolates between the adjacent elements, matching standard percentile/quartile defaults (e.g., NumPy's `linear` method).

